An **array** is a linear data structure storing elements of the same type in contiguous memory locations with O(1) random access via indices.

```python
# Python Array Operations
class ArrayOperations:
    @staticmethod
    def traverse(arr):
        """O(n) - visit each element"""
        for i, element in enumerate(arr):
            print(f"Index {i}: {element}")
        return [element for element in arr]

    @staticmethod
    def insert(arr, index, value):
        """O(n) - shifting elements"""
        arr.insert(index, value)
        return arr

    @staticmethod
    def delete(arr, index):
        """O(n) - shifting elements"""
        if 0 <= index < len(arr):
            return arr.pop(index)
        return None

    @staticmethod
    def linear_search(arr, target):
        """O(n) - brute force"""
        for i, element in enumerate(arr):
            if element == target:
                return i
        return -1

    @staticmethod
    def binary_search(arr, target):
        """O(log n) - requires sorted array"""
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                return mid
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return -1

# Usage
arr = [10, 20, 30, 40, 50]
print("Traverse:", ArrayOperations.traverse(arr))
print("Insert 25 at index 2:", ArrayOperations.insert(arr, 2, 25))
print("Delete at index 3:", ArrayOperations.delete(arr, 3))
print("Linear search 40:", ArrayOperations.linear_search(arr, 40))
print("Binary search 40:", ArrayOperations.binary_search([10,20,30,40,50], 40))
```

