**Array Time Complexities:**

| Operation | Time Complexity |
|-----------|-----------------|
| Access by index | O(1) |
| Search (unsorted) | O(n) |
| Search (sorted - binary) | O(log n) |
| Insert at end | O(1)* |
| Insert at beginning/middle | O(n) |
| Delete from end | O(1)* |
| Delete from beginning/middle | O(n) |
| Traversal | O(n) |

*Amortized for dynamic arrays

**When to use arrays:**
- Fixed-size collections
- Frequent random access by index
- Memory efficiency (contiguous)
- Cache-friendly iteration

A **linked list** is a linear data structure where elements (nodes) are connected via pointers/references. Each node contains data and a reference to the next node.

```python
# Python Singly Linked List
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    # Traversal O(n)
    def traverse(self):
        elements = []
        current = self.head
        while current:
            elements.append(current.data)
            current = current.next
        return elements

    # Insert at beginning O(1)
    def insert_at_beginning(self, data):
        new_node = Node(data)
        new_node.next = self.head
        self.head = new_node

    # Insert at end O(n)
    def insert_at_end(self, data):
        new_node = Node(data)
        if not self.head:
            self.head = new_node
            return
        current = self.head
        while current.next:
            current = current.next
        current.next = new_node

    # Insert at position O(n)
    def insert_at_position(self, data, position):
        if position == 0:
            self.insert_at_beginning(data)
            return
        new_node = Node(data)
        current = self.head
        for _ in range(position - 1):
            if not current:
                raise IndexError("Position out of bounds")
            current = current.next
        new_node.next = current.next
        current.next = new_node

    # Delete by value O(n)
    def delete_by_value(self, value):
        if not self.head:
            return
        if self.head.data == value:
            self.head = self.head.next
            return
        current = self.head
        while current.next and current.next.data != value:
            current = current.next
        if current.next:
            current.next = current.next.next

    # Delete at position O(n)
    def delete_at_position(self, position):
        if not self.head:
            return
        if position == 0:
            self.head = self.head.next
            return
        current = self.head
        for _ in range(position - 1):
            if not current.next:
                raise IndexError("Position out of bounds")
            current = current.next
        if current.next:
            current.next = current.next.next

    # Search O(n)
    def search(self, value):
        current = self.head
        position = 0
        while current:
            if current.data == value:
                return position
            current = current.next
            position += 1
        return -1

    # Reverse linked list O(n)
    def reverse(self):
        prev = None
        current = self.head
        while current:
            next_node = current.next
            current.next = prev
            prev = current
            current = next_node
        self.head = prev

    # Get length O(n)
    def length(self):
        count = 0
        current = self.head
        while current:
            count += 1
            current = current.next
        return count

    # Detect cycle (Floyd's algorithm) O(n)
    def has_cycle(self):
        slow = fast = self.head
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next
            if slow == fast:
                return True
        return False

# Usage
ll = LinkedList()
ll.insert_at_end(10)
ll.insert_at_end(20)
ll.insert_at_end(30)
ll.insert_at_beginning(5)
ll.insert_at_position(15, 2)
print("List:", ll.traverse())  # [5, 10, 15, 20, 30]
ll.reverse()
print("Reversed:", ll.traverse())  # [30, 20, 15, 10, 5]
print("Search 15:", ll.search(15))  # 2
print("Length:", ll.length())  # 5
```

